import sys
from collections import deque

def can_convert(s, t):
    return sorted(s) == sorted(t)

def min_operations(s, t):
    n = len(s)
    count = [0] * 2
    for i in range(n):
        count[int(s[i])] += 1
        count[int(t[i])] -= 1
        if count[0] < 0 or count[1] < 0:
            return -1
    if count[0] != 0 or count[1] != 0:
        return -1

    queue = deque()
    for i in range(n):
        if s[i] == '1':
            queue.append(i)

    operations = 0
    for i in range(n):
        if t[i] == '1':
            if not queue:
                return -1
            if queue[0] < i:
                operations += 1
            queue.popleft()

    return operations

def main():
